<article class="book-detail"><div class="book-cover">📚</div><div><span class="eyebrow">BOOK</span><h1><?=e($b['title'])?></h1><p class="author">مؤلف: <?php if($b['author_id']):?><a href="/author?id=<?=$b['author_id']?>"><?=e($b['author'])?></a><?php else:?>—<?php endif;?></p><div class="chips"><?php foreach($cats as $c):?><a href="/category?id=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="meta"><span>زبان: <?=e($b['language_code'])?></span><span>جلد: <?=e($b['volumes'])?></span><span>صفحات: <?=e($b['pages']?:'—')?></span><span>بازدید: <?=number_format($b['views'])?></span></div></div></article><section class="prose"><h2>معرفی کتاب</h2><p><?=nl2br(e($b['description']?:'معرفی این اثر هنوز توسط مدیریت تکمیل نشده است.'))?></p><h2>شرح و توضیحات</h2><p><?=nl2br(e($b['full_description']?:'توضیحات کامل کتاب، ساختار، سطح علمی و ارتباط آن با سایر آثار از پنل مدیریت قابل تکمیل است.'))?></p><h2>جلدها و دانلود</h2><div class="volumes"><?php foreach($vols as $v):?><div><strong>جلد <?=e($v['volume_no'])?></strong><span><?=e($v['volume_title'])?></span><?php if($v['file_path']||$v['external_url']):?><a class="btn" href="/download?id=<?=$v['id']?>">دانلود</a><?php else:?><small>فایل هنوز اضافه نشده</small><?php endif;?></div><?php endforeach;?></div></section><?php if($related):?><section><h2>کتاب‌های مرتبط</h2><div class="author-grid"><?php foreach($related as $r):?><a href="/book?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong><small><?=e($r['author']??'')?></small></a><?php endforeach;?></div></section><?php endif; ?>
